import{_ as e,o as a,c as r,a2 as s}from"./chunks/framework.F7eQ-ohH.js";const p="/bzygq/assets/quesion_imgs_15f27e4843d347a6b0c79bbca7bb5c20.BxZa3Oxr.png",n="/bzygq/assets/quesion_imgs_ee35b6c2e65e4c1697ee19178c6d114c.--PumCQI.png",o="/bzygq/assets/quesion_imgs_9642b15e4ba4423db11ab763ed73706e.CRrmMctv.png",i="/bzygq/assets/quesion_imgs_6d8f16b754c44b49b26b7e7099327842.BGpXqEl3.png",_="/bzygq/assets/quesion_imgs_2e3e5ae21cff4614b0b08fea06b288dd.2hZuZpvY.png",f=JSON.parse('{"title":"8.点的数量","description":"","frontmatter":{},"headers":[],"relativePath":"行测/逻辑推理/1.图形推理/8.点的数量.md","filePath":"行测/逻辑推理/1.图形推理/8.点的数量.md","lastUpdated":1788883925000}'),d={name:"行测/逻辑推理/1.图形推理/8.点的数量.md"};function c(h,t,b,l,m,g){return a(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="_8-点的数量" tabindex="-1">8.点的数量 <a class="header-anchor" href="#_8-点的数量" aria-label="Permalink to &quot;8.点的数量&quot;">​</a></h1><p>行测中的“点的数量”题型主要考察的是考生对图形中交点、切点等点的数量的理解和识别能力。这类题目通常会给出一组图形，要求考生根据图形中的点的数量找出规律或选择合适的答案。下面我将从几个方面系统地介绍这一题型：</p><h1 id="点的数量基本考法" tabindex="-1">点的数量基本考法 <a class="header-anchor" href="#点的数量基本考法" aria-label="Permalink to &quot;点的数量基本考法&quot;">​</a></h1><p><img src="'+p+'" alt=""></p><table tabindex="0"><thead><tr><th>交点数量：要求找出其中的交点数量，观察图形中的线条，统计交点的数量。</th></tr></thead></table><table tabindex="0"><thead><tr><th>切点数量：要求找出其中的切点数量。观察图形中的线条与圆的接触点，统计切点的数量。</th></tr></thead></table><table tabindex="0"><thead><tr><th>曲直交点：要求找出其中的曲直交点数量。观察图形中的直线与曲线的交点，统计曲直交点的数量。</th></tr></thead></table><table tabindex="0"><thead><tr><th>曲曲交点：要求找出其中的曲曲交点数量。观察图形中的两条曲线的交点，统计曲曲交点的数量。</th></tr></thead></table><table tabindex="0"><thead><tr><th>圈内点和圈外点：要求找出其中的圈内点和圈外点的数量。观察图形中的封闭图形，统计圈内点和圈外点的数量。</th></tr></thead></table><h1 id="真题" tabindex="-1">真题 <a class="header-anchor" href="#真题" aria-label="Permalink to &quot;真题&quot;">​</a></h1><p><strong>例1： 从所给四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：</strong></p><p><img src="'+n+'" alt=""></p><p>解析：考查交点的数量，第一组图形中，每个图形都是杂乱且相交的，交点数量都为2；第二组图形，前两个图形的元素是相交的，并且交点数量为3，那么第三个图形的交点数量也应为3，只有C符合。</p><p><strong>例2：从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性。</strong></p><p><img src="'+o+'" alt=""></p><p>解析：考查切点，观察发现，题干每幅图形均存在曲线与直线，且曲直相交，优先考虑曲直交点数。题干每幅图形的曲直交点数均为2个，但无法得出唯一答案。继续观察发现，题干图形相切明显，考虑切点数，每幅图的切点数均为1个，只有C项符合规律。</p><p><strong>例3：从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定规律性：</strong></p><p><img src="'+i+'" alt=""></p><p>解析：考查<a href="https://zhida.zhihu.com/search?content_id=234435568&amp;content_type=Article&amp;match_order=3&amp;q=%E6%9B%B2%E7%9B%B4%E4%BA%A4%E7%82%B9&amp;zhida_source=entity" target="_blank" rel="noreferrer">曲直交点</a>数量；元素组成凌乱，观察图形均由直线和曲线构成，且曲线和直线都有交点。</p><p>观察发现，题干中图形直线与曲线的交点数目依次为2、3、4、5、?，问号处应该填入直线与曲线有6个交点的选项，只有B项满足。</p><p>故正确答案为B。</p><p><strong>例4：从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：</strong></p><p><img src="'+_+'" alt=""></p><p>解析：考查圆内部交点；观察题干发现，直接数交点并无规律，但每个图形都有一个圆，发现第一行所有图形圆内的交点都为1，第二行所有图形圆内的交点都为2，第三行前两幅图形圆内的交点都为3，故“？”处图形圆内的交点也应为3。A、B、C、D项分别为4、2、3、1，C项当选。故正确答案为C。</p>',24)])])}const q=e(d,[["render",c]]);export{f as __pageData,q as default};
